clinics_table = sa.table("clinics", sa.column("id", sa.UUID()))
templates_table = sa.table(
    "document_templates",
    sa.column("id", sa.UUID()),
    sa.column("clinic_id", sa.UUID()),
    sa.column("code", sa.String()),
    sa.column("name", sa.String()),
    sa.column("version", sa.Integer()),
    sa.column("html_content", sa.Text()),
    sa.column("supersedes_id", sa.UUID()),
    sa.column("is_current", sa.Boolean()),
)


def upgrade() -> None:
    conn = op.get_bind()
    clinic_ids = [row.id for row in conn.execute(sa.select(clinics_table.c.id))]

    # Paso 1: ubicar y retirar las versiones de ejemplo vigentes.
    legacy_current: dict[tuple, tuple] = {}
    for row in conn.execute(
        sa.select(
            templates_table.c.id,
            templates_table.c.clinic_id,
            templates_table.c.code,
            templates_table.c.version,
        ).where(
            templates_table.c.is_current.is_(True),
            templates_table.c.code.in_(LEGACY_CODES_TO_RETIRE),
        )
    ):
        legacy_current[(row.clinic_id, row.code)] = (row.id, row.version)

    if legacy_current:
        conn.execute(
            templates_table.update()
            .where(templates_table.c.id.in_([v[0] for v in legacy_current.values()]))
            .values(is_current=False)
        )

    # Paso 2: codigos reales ya vigentes (tras retirar lo anterior), para no duplicar.
    existing_real_current: dict = {}
    for row in conn.execute(
        sa.select(templates_table.c.clinic_id, templates_table.c.code).where(
            templates_table.c.is_current.is_(True)
        )
    ):
        existing_real_current.setdefault(row.clinic_id, set()).add(row.code)

    rows_to_insert = []
    for clinic_id in clinic_ids:
        already = existing_real_current.get(clinic_id, set())
        for code, name, html_content in DEFAULT_TEMPLATES:
            if code in already:
                continue
            legacy = legacy_current.get((clinic_id, code))
            rows_to_insert.append(
                {
                    "id": uuid.uuid4(),
                    "clinic_id": clinic_id,
                    "code": code,
                    "name": name,
                    "version": (legacy[1] + 1) if legacy else 1,
                    "html_content": html_content,
                    "supersedes_id": legacy[0] if legacy else None,
                    "is_current": True,
                }
            )

    if rows_to_insert:
        op.bulk_insert(templates_table, rows_to_insert)


def downgrade() -> None:
    # No reversible de forma segura: no hay como distinguir un formato real
    # insertado por esta migracion de uno creado despues a mano con el mismo
    # codigo, ni reconstruir el contenido exacto de los 4 ejemplos retirados
    # (mismo criterio ya documentado en 9f3a1c7b2d4e).
    pass
